// @generated by:gauntlet run:godseye-e08-independent-gauntlet
import { randomUUID } from "node:crypto";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { IncidentEngine, type IncidentNotifier } from "../packages/core/src/incidents.js";
import {
  type E08ObservabilityFixture,
  e08ObservabilityFixture,
} from "./helpers/e08-observability.js";
import { required } from "./helpers/e08-values.js";

describe("E08 eligible notification fairness", () => {
  let f: E08ObservabilityFixture;
  beforeEach(async () => {
    f = await e08ObservabilityFixture();
    await f.register();
  });
  afterEach(async () => {
    await f.store.close();
  });
  const engine = (notifier?: IncidentNotifier) =>
    new IncidentEngine(f.store, {
      now: f.clock.now,
      notifier,
      sources: {
        backups: (actor) => f.infrastructure.recovery.backups(actor),
        rotations: (actor) => f.infrastructure.rotation.overview(actor),
        observability: (actor) => f.engine.incidentFindings(actor),
      },
    });
  const first = async () =>
    required((await engine().evaluate(f.freshOwner(), randomUUID())).incidents[0]);
  it("T-AC-813 delivers a later eligible incident while the earlier incident is muted", async () => {
    const original = await first();
    await engine().mute(
      f.freshOwner(),
      original.id,
      {
        expectedRevision: original.revision,
        until: new Date(f.clock.now().getTime() + 60000).toISOString(),
      },
      randomUUID(),
    );
    await f.register({ name: "second-eligible-source" });
    const sent: string[] = [];
    const notifier: IncidentNotifier = {
      async notify(view) {
        sent.push(view.id);
        return { state: "notified" };
      },
    };
    const result = await engine(notifier).evaluate(f.freshOwner(), randomUUID());
    const second = required(result.incidents.find((row) => row.id !== original.id));
    await engine(notifier).deliver();
    expect(sent).toEqual([second.id]);
  });
  it("T-AC-813 delivers a later incident after an earlier notification exhausts its finite attempts", async () => {
    const original = await first();
    let firstAttempts = 0;
    const sent: string[] = [];
    const notifier: IncidentNotifier = {
      async notify(view) {
        if (view.id === original.id) {
          firstAttempts++;
          return { state: "failed" };
        }
        sent.push(view.id);
        return { state: "notified" };
      },
    };
    for (let index = 0; index < 3; index++) await engine(notifier).deliver();
    await f.register({ name: "second-after-exhaustion" });
    const result = await engine(notifier).evaluate(f.freshOwner(), randomUUID());
    const second = required(result.incidents.find((row) => row.id !== original.id));
    await engine(notifier).deliver();
    expect(firstAttempts).toBe(3);
    expect(sent).toEqual([second.id]);
  });
});
